import { useEffect, useState } from 'react'
import { useThree } from '@react-three/fiber'
import * as THREE from 'three'
import { asset } from '../../utils/asset'

// The grain tiles generated by scripts/make-textures.mjs, as repeating
// textures. A tile is handed over only once loaded: a material compiled
// around an empty texture would draw black.

export const PAPER_TILE = asset('assets/textures/paper-grain.webp')
export const WOOD_TILE = asset('assets/textures/wood-grain.webp')

/** A repeating tile, `repeatX` × `repeatY` times over the surface, or null while it loads. */
export const useTile = (url, repeatX, repeatY) => {
  const invalidate = useThree((state) => state.invalidate)
  const [texture, setTexture] = useState(null)

  useEffect(() => {
    let alive = true
    const tile = new THREE.TextureLoader().load(url, () => {
      if (!alive) return
      setTexture(tile)
      invalidate()
    })
    tile.wrapS = THREE.RepeatWrapping
    tile.wrapT = THREE.RepeatWrapping
    tile.repeat.set(repeatX, repeatY)
    tile.colorSpace = THREE.SRGBColorSpace
    tile.anisotropy = 8
    return () => {
      alive = false
      tile.dispose()
    }
  }, [url, repeatX, repeatY, invalidate])

  return texture
}
